def test_real_http_safe_errors(server):
    with httpx.Client(base_url=server, timeout=3, trust_env=False) as client:
        assert client.get("/health").json() == {"status": "ok"}
        cases = [(client.get("/missing"), 404, "resource_not_found"),
                 (client.post("/probe/validate", json={"count": SENTINEL}), 422, "validation_failed"),
                 (client.get("/probe/unexpected"), 500, "internal_error"),
                 (client.get("/probe/challenge"), 401, "authentication_required"),
                 (client.get("/probe/retry"), 503, "dependency_unavailable"),
                 (client.post("/health"), 405, "http_error")]
        for result, status, identifier in cases:
            assert result.status_code == status
            body = result.json()
            assert set(body) == {"error", "error_id"}
            assert isinstance(body["error"], str)
            assert body["error_id"] == identifier
            assert SENTINEL not in result.text
        assert cases[3][0].headers["www-authenticate"] == "Bearer"
        assert cases[4][0].headers["retry-after"] == "2"
        assert "GET" in cases[5][0].headers["allow"]
        assert client.get("/probe/validate").status_code == 405
        assert client.get("/health").status_code == 200


def test_protocol_headers_and_numeric_code(server):
    with httpx.Client(base_url=server, timeout=3, trust_env=False) as client:
        redirect = client.get("/probe/redirect")
        assert redirect.status_code == 307
        assert redirect.headers["location"] == "/health"
        invalid_range = client.get("/probe/range")
        assert invalid_range.status_code == 416
        assert invalid_range.headers["content-range"] == "bytes */12"
        result = client.get("/probe/code")
        assert result.status_code == 409
        assert result.json() == {"error": "safe", "error_id": "known", "code": 17}
        assert type(result.json()["code"]) is int
        client.get("/probe/unexpected")


def test_completed_and_incomplete_response_failures(server):
    with httpx.Client(base_url=server, timeout=3, trust_env=False) as client:
        completed = client.get("/probe/background")
        assert completed.status_code == 200
        assert completed.content == b"complete"
        with client.stream("GET", "/probe/incomplete") as incomplete:
            # The original response remains a failed/truncated200, never a500.
            assert incomplete.status_code == 200
            chunks = []
            with pytest.raises(httpx.RemoteProtocolError):
                for chunk in incomplete.iter_raw():
                    chunks.append(chunk)
            assert b"".join(chunks) == b"x"
        assert client.get("/health").status_code == 200
